// ─── File: RecoDemo.java ───
// Runnable demo. Each class would be its own file in a real project.
package com.bank.reco;

import java.util.*;
import java.util.logging.*;
import java.util.stream.Collectors;

public class RecoDemo {
    private static final Logger log = Logger.getLogger(RecoDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Catalog of products
        List<Product> catalog = List.of(
                new Product("HOME_LOAN", "Home Loan", "loan", "high"),
                new Product("PERSONAL_LOAN", "Personal Loan", "loan", "high"),
                new Product("FIXED_DEPOSIT", "Fixed Deposit", "savings", "low"),
                new Product("RECURRING_DEPOSIT", "Recurring Deposit", "savings", "low"),
                new Product("CREDIT_CARD", "Credit Card", "card", "medium"));

        // Who holds what (interaction matrix)
        Map<String, Set<String>> holdings = new HashMap<>();
        holdings.put("SAV2001", new HashSet<>(Set.of("FIXED_DEPOSIT")));             // Rajesh
        holdings.put("CUR3001", new HashSet<>(Set.of("CREDIT_CARD")));               // Priya
        holdings.put("OTHER1", new HashSet<>(Set.of("FIXED_DEPOSIT", "RECURRING_DEPOSIT")));
        holdings.put("OTHER2", new HashSet<>(Set.of("FIXED_DEPOSIT", "HOME_LOAN")));

        // Popularity from global counts
        Map<String, Integer> popularity = Map.of(
                "FIXED_DEPOSIT", 500, "HOME_LOAN", 400, "CREDIT_CARD", 300,
                "RECURRING_DEPOSIT", 250, "PERSONAL_LOAN", 150);

        PopularityRecommender pop = new PopularityRecommender(popularity);
        CollaborativeRecommender collab = new CollaborativeRecommender(holdings);
        ContentBasedRecommender content = new ContentBasedRecommender(catalog);
        HybridRecommender hybrid = new HybridRecommender(pop, collab, content, holdings, 2);

        CandidateStore store = new CandidateStore();
        // Offline precompute candidates for each user
        for (String user : List.of("SAV2001", "CUR3001", "NEWCUST"))
            store.put(user, hybrid.recommend(user, catalog, 3));

        Ranker ranker = new Ranker();
        EventTracker tracker = new EventTracker();

        // Real-time: Rajesh opens app → rank precomputed candidates with fresh context
        List<String> rajesh = ranker.rank(store.get("SAV2001"), "evening");
        log.info("Rajesh (holds FD, rich signal): " + rajesh);
        tracker.record("SAV2001", "HOME_LOAN", "CLICK");

        List<String> priya = ranker.rank(store.get("CUR3001"), "morning");
        log.info("Priya (holds credit card):      " + priya);

        // New customer → cold-start → popularity + content fallback
        List<String> fresh = ranker.rank(store.get("NEWCUST"), "evening");
        log.info("New customer (cold-start):       " + fresh);
    }
}

