class Product {
    final String id, name, category, risk;
    Product(String id, String name, String category, String risk) {
        this.id = id; this.name = name; this.category = category; this.risk = risk;
    }
}

// ─── baseline/PopularityRecommender.java ───
// Simplest baseline: most popular products. Great fallback and cold-start answer.
class PopularityRecommender {
    private final Map<String, Integer> popularity;
    PopularityRecommender(Map<String, Integer> popularity) { this.popularity = popularity; }
    List<String> recommend(int n) {
        return popularity.entrySet().stream()
                .sorted((a, b) -> b.getValue() - a.getValue())
                .limit(n).map(Map.Entry::getKey).collect(Collectors.toList());
    }
    int score(String productId) { return popularity.getOrDefault(productId, 0); }
}

// ─── collab/CollaborativeRecommender.java ───
// "Users who hold X also hold Y" using co-occurrence over holdings.
class CollaborativeRecommender {
    private final Map<String, Set<String>> holdings;
    CollaborativeRecommender(Map<String, Set<String>> holdings) { this.holdings = holdings; }
    Map<String, Integer> scores(String userId) {
        Set<String> mine = holdings.getOrDefault(userId, Set.of());
        Map<String, Integer> candidateScores = new HashMap<>();
        for (Map.Entry<String, Set<String>> e : holdings.entrySet()) {
            if (e.getKey().equals(userId)) continue;
            Set<String> theirs = e.getValue();
            if (Collections.disjoint(mine, theirs)) continue;    // similar user shares something
            for (String p : theirs)
                if (!mine.contains(p)) candidateScores.merge(p, 1, Integer::sum);
        }
        return candidateScores;   // e.g. others with FD also hold HOME_LOAN, RECURRING_DEPOSIT
    }
}

// ─── content/ContentBasedRecommender.java ───
// Recommend products with attributes similar to what the user holds.
class ContentBasedRecommender {
    private final Map<String, Product> byId = new HashMap<>();
    ContentBasedRecommender(List<Product> catalog) { for (Product p : catalog) byId.put(p.id, p); }
    Map<String, Integer> scores(Set<String> held) {
        Map<String, Integer> s = new HashMap<>();
        for (String h : held) {
            Product hp = byId.get(h);
            if (hp == null) continue;
            for (Product p : byId.values())
                if (!held.contains(p.id) && p.category.equals(hp.category))
                    s.merge(p.id, 2, Integer::sum);              // same category → similar
        }
        return s;
    }
}

