// Blend collaborative + content + popularity; handle cold-start by falling back.
class HybridRecommender {
    private static final Logger log = Logger.getLogger(HybridRecommender.class.getName());
    private final PopularityRecommender pop; private final CollaborativeRecommender collab;
    private final ContentBasedRecommender content; private final Map<String, Set<String>> holdings;
    private final int minInteractions;
    HybridRecommender(PopularityRecommender pop, CollaborativeRecommender collab,
                      ContentBasedRecommender content, Map<String, Set<String>> holdings, int minInteractions) {
        this.pop = pop; this.collab = collab; this.content = content;
        this.holdings = holdings; this.minInteractions = minInteractions;
    }
    List<String> recommend(String userId, List<Product> catalog, int n) {
        Set<String> held = holdings.getOrDefault(userId, Set.of());
        if (held.size() < minInteractions) {               // COLD START
            log.info("cold-start for " + userId + " → popularity + content fallback");
            return pop.recommend(n);
        }
        Map<String, Double> blended = new HashMap<>();
        collab.scores(userId).forEach((p, s) -> blended.merge(p, s * 0.5, Double::sum));
        content.scores(held).forEach((p, s) -> blended.merge(p, s * 0.3, Double::sum));
        for (String p : blended.keySet()) blended.merge(p, pop.score(p) * 0.001, Double::sum);
        return blended.entrySet().stream()
                .sorted((a, b) -> Double.compare(b.getValue(), a.getValue()))
                .limit(n).map(Map.Entry::getKey).collect(Collectors.toList());
    }
}

