// Offline-precomputed candidates per user.
class CandidateStore {
    private final Map<String, List<String>> candidates = new HashMap<>();
    void put(String userId, List<String> c) { candidates.put(userId, c); }
    List<String> get(String userId) { return candidates.getOrDefault(userId, List.of()); }
}

