// Captures impressions/clicks/conversions that become training labels.
class EventTracker {
    private static final Logger log = Logger.getLogger(EventTracker.class.getName());
    void record(String userId, String productId, String eventType) {
        log.info("FEEDBACK " + userId + " " + eventType + " on " + productId + " → training signal");
    }
}

